<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility\TemplateVersionVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVersionCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVersionVisibilityService $visibility,
        private readonly TemplateVersionWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Template version");
        $span = $this->startSpan("Check allow of create usecase for Template version");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVersionCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(TemplateVersionCreateParams $params): TemplateVersionCreateResult
    {
        $this->logDebug("Run create usecase for Template version");
        $span = $this->startSpan("Run create usecase for Template version");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Template version');
            }
            $this->dispatcher->dispatch(new TemplateVersionCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new TemplateVersionCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = TemplateVersion::create($input);
            $result = $this->writer->create(
                $entity,
                fn (TemplateVersion $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateVersionCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
